using System;
using System.Collections.Generic;
using UnityEngine;
namespace SurvivalLegend.Data { [CreateAssetMenu(fileName="Character",menuName="Survival Legend/Character")] public sealed class CharacterDefinition:ContentDefinition { public string DisplayName,Subtitle,Traits,Color="#ffffff",BasicKind="projectile",BasicWeapon="bow"; public StatDefinition Stats=new StatDefinition(); public SkillDefinition[] Skills=new SkillDefinition[4]; public float AnimationStride,AttackDuration,ChainRange; public float[] ChainRatios=Array.Empty<float>(); public CharacterData ToData(){var ids=new string[Skills==null?0:Skills.Length];for(var i=0;i<ids.Length;i++)ids[i]=Skills[i].Id;return new CharacterData(Id,DisplayName,Subtitle,Traits,Color,BasicKind,Stats.ToData(),ids,AnimationStride,AttackDuration,BasicWeapon,ChainRatios==null?Array.Empty<float>():(float[])ChainRatios.Clone(),ChainRange);} internal void Validate(IList<SkillDefinition> registry,List<string> errors){if(Stats==null)errors.Add("Character '"+Id+"' needs Stats.");if(Skills==null||Skills.Length!=4)errors.Add("Character '"+Id+"' must reference exactly four skills.");else for(var i=0;i<Skills.Length;i++)if(Skills[i]==null||!registry.Contains(Skills[i]))errors.Add("Character '"+Id+"' has a missing or unregistered skill at slot "+i+".");} } }
